export function buildPlanImpactAlignment({distribution,topics=[],impactForTopic}={}){
  const planned=(distribution?.rows||[]).filter(r=>r.subjectId!=='unassigned'&&r.plannedMinutes>0);
  if(planned.length<2)return {state:'insufficient',reason:'Planeje tempo para pelo menos duas disciplinas nesta semana.'};
  const rows=planned.map(r=>{
    const subjectTopics=topics.filter(topic=>topic.subjectId===r.subjectId);
    const impacts=subjectTopics.map(impactForTopic).filter(value=>Number.isFinite(value)&&value>=0&&value<=100);
    const coverage=subjectTopics.length?impacts.length/subjectTopics.length:0;
    return {...r,topicCount:subjectTopics.length,impactCount:impacts.length,coverage,averageImpact:impacts.length?impacts.reduce((sum,value)=>sum+value,0)/impacts.length:null};
  });
  if(rows.some(r=>r.coverage<.5||r.impactCount<1))return {state:'insufficient',reason:'O impacto estimado cobre menos da metade dos tópicos de alguma disciplina planejada.'};
  const impactTotal=rows.reduce((sum,r)=>sum+r.averageImpact,0);
  const plannedTotal=rows.reduce((sum,r)=>sum+r.plannedMinutes,0);
  if(!impactTotal)return {state:'insufficient',reason:'Ainda não há impacto estimado para comparar as disciplinas planejadas.'};
  return {state:'ready',rows:rows.map(r=>({...r,plannedShare:r.plannedMinutes/plannedTotal*100,impactShare:r.averageImpact/impactTotal*100})),subjectCount:rows.length};
}
